    public decimal Subtract(Operands operands)
    {
        Console.WriteLine($"Subtracting {operands.OperandTwo} from {operands.OperandOne}"); 
        return decimal.Parse(operands.OperandOne) - decimal.Parse(operands.OperandTwo);
    }
}

